"use client";

import { Calendar } from "lucide-react";
import { useId, useState } from "react";
import {
  Area,
  AreaChart,
  CartesianGrid,
  Line,
  ReferenceLine,
  XAxis,
} from "recharts";

import { Button } from "@/components/ui/button";
import { ArrowDown01Icon } from "../../assets/icons";
import {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
} from "@/components/ui/chart";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { circulationData } from "../../data";
import { cn } from "../../lib/utils";

type CirculationTimeframe = "weekly" | "monthly" | "yearly";

type CirculationDataPoint = {
  timestamp: number;
  checkouts: number;
  returns: number;
};

const circulationChartConfig = {
  checkouts: {
    label: "Checkouts",
    color: "var(--primary)",
  },
  returns: {
    label: "Returns",
    color: "var(--muted-foreground)",
  },
} satisfies ChartConfig;

const chartTicks: Record<CirculationTimeframe, number[]> = {
  weekly: circulationData.weekly.map((point) => point.timestamp),
  monthly: [0, 7, 14, 21].map(
    (dayIndex) => circulationData.monthly[dayIndex].timestamp,
  ),
  yearly: circulationData.yearly
    .filter((_, month) => month % 2 === 0)
    .map((point) => point.timestamp),
};

const chartDomains: Record<CirculationTimeframe, [number, number]> = {
  weekly: [
    circulationData.weekly[0].timestamp,
    circulationData.weekly[circulationData.weekly.length - 1].timestamp,
  ],
  monthly: [
    circulationData.monthly[0].timestamp,
    circulationData.monthly[circulationData.monthly.length - 1].timestamp,
  ],
  yearly: [
    circulationData.yearly[0].timestamp,
    circulationData.yearly[circulationData.yearly.length - 1].timestamp,
  ],
};

const chartMidpoints: Record<CirculationTimeframe, number[]> = {
  weekly: getMidpoints(chartTicks.weekly, chartDomains.weekly[1]),
  monthly: getMidpoints(chartTicks.monthly, chartDomains.monthly[1]),
  yearly: getMidpoints(chartTicks.yearly, chartDomains.yearly[1]),
};

function getMidpoints(ticks: number[], domainEnd: number) {
  const points = ticks.at(-1) === domainEnd ? ticks : [...ticks, domainEnd];

  return points.slice(0, -1).map((tick, index) => {
    return tick + (points[index + 1] - tick) / 2;
  });
}

const shortWeekdayFormatter = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  timeZone: "UTC",
});
const shortDateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  timeZone: "UTC",
});
const shortMonthFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  timeZone: "UTC",
});

const chartFormatters: Record<CirculationTimeframe, (value: number) => string> =
  {
    weekly: (value) => shortWeekdayFormatter.format(value),
    monthly: (value) => shortDateFormatter.format(value),
    yearly: (value) => shortMonthFormatter.format(value),
  };

const weeklyTooltipFormatter = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  month: "short",
  day: "numeric",
  timeZone: "UTC",
});
const datedTooltipFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});
const monthlyTooltipFormatter = new Intl.DateTimeFormat("en-US", {
  month: "long",
  year: "numeric",
  timeZone: "UTC",
});

function formatTooltipDate(timeframe: CirculationTimeframe, value: number) {
  if (timeframe === "weekly") return weeklyTooltipFormatter.format(value);
  if (timeframe === "monthly") return datedTooltipFormatter.format(value);
  return monthlyTooltipFormatter.format(value);
}

export function CirculationChart() {
  const [timeframe, setTimeframe] = useState<CirculationTimeframe>("weekly");
  const gradientId = useId().replace(/:/g, "");

  return (
    <div>
      <div className="flex w-full items-center justify-between">
        <h2 className="text-lg font-semibold">Collection Circulation</h2>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="sm" className="capitalize">
              {timeframe}
              <ArrowDown01Icon className="text-muted-foreground size-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-32">
            <DropdownMenuGroup>
              {(["weekly", "monthly", "yearly"] as const).map((option) => (
                <DropdownMenuItem
                  key={option}
                  onClick={() => setTimeframe(option)}
                  className={cn(
                    timeframe === option && "text-primary font-semibold",
                  )}
                >
                  {option[0].toUpperCase() + option.slice(1)}
                </DropdownMenuItem>
              ))}
            </DropdownMenuGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      <ChartContainer
        config={circulationChartConfig}
        className="bg-card mt-5 h-84 w-full [&_.recharts-surface]:overflow-visible"
        onMouseDown={(event) => event.preventDefault()}
      >
        <AreaChart
          data={circulationData[timeframe]}
          accessibilityLayer={false}
          margin={{ left: 0, right: 0, top: 16, bottom: 24 }}
          style={{ overflow: "visible" }}
        >
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="var(--primary)" stopOpacity={0.15} />
              <stop
                offset="95%"
                stopColor="var(--primary)"
                stopOpacity={0.01}
              />
            </linearGradient>
          </defs>
          <CartesianGrid vertical horizontal={false} stroke="var(--border)" />
          {chartMidpoints[timeframe].map((midpoint) => (
            <ReferenceLine
              key={midpoint}
              x={midpoint}
              stroke="var(--border)"
              strokeDasharray="8 8"
            />
          ))}
          <XAxis
            dataKey="timestamp"
            type="number"
            domain={chartDomains[timeframe]}
            stroke="var(--muted-foreground)"
            fontSize={12}
            tickLine={false}
            axisLine={false}
            ticks={chartTicks[timeframe]}
            minTickGap={0}
            interval={0}
            padding={{ left: 0, right: 0 }}
            tick={({ x, y, payload }) => (
              <text
                x={x}
                y={y}
                dy={16}
                fill="var(--muted-foreground)"
                fontSize={12}
                textAnchor="middle"
                className="font-medium"
              >
                {chartFormatters[timeframe](payload.value)}
              </text>
            )}
          />
          <ChartTooltip
            cursor={{
              stroke: "var(--primary)",
              strokeWidth: 1,
              className: "!stroke-primary",
            }}
            content={({ active, payload }) => {
              if (!active || !payload?.length) return null;

              const point = payload[0].payload as CirculationDataPoint;

              return (
                <div className="bg-foreground text-background border-foreground/10 z-50 flex w-52 flex-col gap-2 rounded-lg border p-3 text-xs shadow-md">
                  <div className="border-background/20 flex items-center gap-2 border-b pb-2">
                    <Calendar className="text-background/80 size-4" />
                    <span className="text-background font-semibold">
                      {formatTooltipDate(timeframe, point.timestamp)}
                    </span>
                  </div>
                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className="bg-primary size-2 shrink-0 rounded-xs" />
                        <span className="text-background/80">Checkouts</span>
                      </div>
                      <span className="text-background font-semibold">
                        {point.checkouts.toLocaleString()}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className="bg-muted-foreground size-2 shrink-0 rounded-xs" />
                        <span className="text-background/80">Returns</span>
                      </div>
                      <span className="text-background font-semibold">
                        {point.returns.toLocaleString()}
                      </span>
                    </div>
                  </div>
                </div>
              );
            }}
          />
          <Area
            type="monotone"
            dataKey="checkouts"
            stroke="var(--primary)"
            strokeWidth={1.5}
            fillOpacity={1}
            fill={`url(#${gradientId})`}
            dot={false}
            activeDot={{
              r: 4,
              stroke: "var(--primary)",
              strokeWidth: 2,
              fill: "var(--card)",
            }}
          />
          <Line
            type="monotone"
            dataKey="returns"
            stroke="var(--muted-foreground)"
            strokeWidth={1.5}
            dot={false}
            activeDot={{
              r: 4,
              stroke: "var(--muted-foreground)",
              strokeWidth: 2,
              fill: "var(--card)",
            }}
          />
        </AreaChart>
      </ChartContainer>
    </div>
  );
}

"use client"

import { useState } from "react"
import {
  Cell,
  Pie,
  PieChart,
  Tooltip,
} from "recharts"

export type CollectionDonutDatum = {
  name: string
  value: number
  fill: string
}

type CollectionDonutChartProps = {
  data: CollectionDonutDatum[]
  total: number
  label: string
  size?: number
}

export function CollectionDonutChart({
  data,
  total,
  label,
  size = 200,
}: CollectionDonutChartProps) {
  const [activeIndex, setActiveIndex] = useState<number | null>(null)

  const activeDatum = activeIndex !== null ? data[activeIndex] : null
  const displayValue = activeDatum ? activeDatum.value : total
  const displayLabel = activeDatum ? activeDatum.name : label

  const center = size / 2
  const outerRadius = size / 2 - 2
  const innerRadius = outerRadius * 0.7

  return (
    <div
      className="relative shrink-0"
      style={{ width: size, height: size }}
      onMouseDown={(event) => event.preventDefault()}
    >
      <PieChart
        width={size}
        height={size}
        margin={{ top: 0, right: 0, bottom: 0, left: 0 }}
      >
        <Pie
          data={data}
          cx={center}
          cy={center}
          dataKey="value"
          innerRadius={innerRadius}
          outerRadius={outerRadius}
          paddingAngle={2}
          startAngle={90}
          endAngle={-270}
          stroke="none"
          onMouseEnter={(_, index) => setActiveIndex(index)}
          onMouseLeave={() => setActiveIndex(null)}
        >
          {data.map((entry, index) => (
            <Cell
              key={`cell-${index}`}
              fill={entry.fill}
              opacity={activeIndex === null || activeIndex === index ? 1 : 0.35}
              style={{ transition: "opacity 300ms ease-in-out" }}
            />
          ))}
        </Pie>
        <Tooltip content={() => null} cursor={false} />
      </PieChart>

      <div
        className="pointer-events-none absolute flex flex-col items-center justify-center text-center"
        style={{
          width: innerRadius * 2,
          height: innerRadius * 2,
          top: center - innerRadius,
          left: center - innerRadius,
        }}
      >
        <div
          key={displayLabel}
          aria-live="polite"
          className="animate-in fade-in slide-in-from-bottom-1 animation-duration-300 flex flex-col items-center"
        >
          <span className="text-foreground text-3xl leading-none font-bold">
            {displayValue.toLocaleString()}
          </span>
          <span className="text-muted-foreground mt-1 text-sm leading-none">
            {displayLabel}
          </span>
        </div>
      </div>
    </div>
  )
}

import { CirculationChart } from "./circulation-chart";
import { CollectionDonutChart } from "./collection-donut-chart";
import {
  ArrowDown01Icon,
  BookPlusIcon,
  CancelIcon,
  CheckoutIcon,
  Download01Icon,
  ReturnIcon,
  SparklesIcon,
  UserAdd02Icon,
} from "../../assets/icons";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  collectionOverview,
  intelligenceCards,
  metrics,
  recentActivity,
} from "../../data";
import { cn } from "../../lib/utils";

const quickActions = [
  { label: "Checkout Items", icon: CheckoutIcon },
  { label: "Process Return", icon: ReturnIcon },
  { label: "Add New Item", icon: BookPlusIcon },
  { label: "Add New Member", icon: UserAdd02Icon },
];

export function DashboardContent() {
  return (
    <>
      <DashboardHeader />
      <div className="@container/dashboard space-y-10">
        <section>
          <SectionTitle>Top Metrics</SectionTitle>
          <div className="mt-3 grid grid-cols-2 gap-3 lg:grid-cols-4">
            {metrics.map((metric) => (
              <MetricCard key={metric.label} {...metric} />
            ))}
          </div>
        </section>

        <section>
          <SectionTitle>Quick Actions</SectionTitle>
          <div className="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-4">
            {quickActions.map((action) => (
              <Card
                key={action.label}
                className="bg-secondary text-secondary-foreground rounded-lg border-0 py-0 shadow-none transition-transform duration-200 ease-out hover:-translate-y-0.5 motion-reduce:transform-none"
              >
                <CardContent className="flex h-full items-center justify-between p-3">
                  <div className="flex items-center gap-2">
                    <div className="bg-background flex size-11 items-center justify-center rounded-lg border">
                      <action.icon className="size-5" />
                    </div>
                    <span className="text-base font-semibold">
                      {action.label}
                    </span>
                  </div>
                  <ArrowDown01Icon className="text-muted-foreground size-6 -rotate-90 transition-transform duration-200 ease-out group-hover/card:translate-x-1 motion-reduce:transform-none" />
                </CardContent>
              </Card>
            ))}
          </div>
        </section>

        <section className="grid grid-cols-1 gap-8 @4xl/dashboard:grid-cols-3">
          <div className="@4xl/dashboard:col-span-2">
            <CirculationChart />
          </div>
          <div>
            <CollectionOverview />
          </div>
        </section>

        <section className="grid grid-cols-1 gap-8 @4xl/dashboard:grid-cols-2">
          <RecentActivity />
          <LibraryIntelligence />
        </section>
      </div>
    </>
  );
}

function SectionTitle({ children }: { children: React.ReactNode }) {
  return <h2 className="text-lg font-semibold">{children}</h2>;
}

function DashboardHeader() {
  return (
    <div className="mb-6 flex items-start justify-between gap-4 sm:mb-10">
      <div>
        <h1 className="text-xl leading-tight font-bold tracking-tight">
          Good Morning <span className="italic">Librarian</span>
        </h1>
        <div className="mt-2 flex flex-col gap-1 text-sm sm:flex-row sm:items-center">
          <p className="text-muted-foreground font-medium italic">
            Springfield Public Library
          </p>
          <span className="text-foreground hidden sm:inline">•</span>
          <p className="text-muted-foreground font-medium">
            Saturday, Feb 19, 2026
          </p>
        </div>
      </div>
      <Button variant="secondary" size="lg" className="shrink-0">
        <span>Export</span>
        <Download01Icon className="size-5 -scale-y-100" />
      </Button>
    </div>
  );
}

function MetricCard({
  icon: Icon,
  iconClassName,
  label,
  note,
  noteIcon: NoteIcon,
  value,
}: {
  label: string;
  value: string;
  note: string;
  icon: React.ComponentType<{ className?: string }>;
  iconClassName: string;
  noteIcon?: React.ComponentType<{ className?: string }>;
}) {
  const noteParts = note.match(/^([+-]?\d+(?:\.\d+)?%?|↓\s*\d+)\s+(.*)$/);

  return (
    <Card className="bg-secondary text-secondary-foreground gap-6 rounded-lg border-0 p-5 shadow-none">
      <div className="flex items-center gap-2">
        <Icon className={cn("size-5 shrink-0", iconClassName)} />
        <span className="text-secondary-foreground text-sm font-medium">
          {label}
        </span>
      </div>
      <div className="space-y-3">
        <h3 className="text-3xl leading-none font-bold tracking-tight">
          {value}
        </h3>
        <p className="flex items-center gap-1 text-xs">
          {NoteIcon && <NoteIcon className="size-3.5 shrink-0" />}
          {noteParts ? (
            <>
              <span className="text-foreground font-semibold">
                {noteParts[1]}
              </span>{" "}
              <span className="text-muted-foreground">{noteParts[2]}</span>
            </>
          ) : (
            <span className="text-muted-foreground">{note}</span>
          )}
        </p>
      </div>
    </Card>
  );
}

function CollectionOverview() {
  const total = collectionOverview.segments.reduce(
    (sum, segment) => sum + segment.count,
    0,
  );
  const segments = collectionOverview.segments.map((segment) => ({
    ...segment,
    percentage: total > 0 ? (segment.count / total) * 100 : 0,
  }));
  const chartData = segments.map((segment) => ({
    name: segment.label,
    value: segment.count,
    fill: `var(--chart-${segment.color})`,
  }));

  return (
    <div>
      <SectionTitle>Collection Overview</SectionTitle>
      <Card className="mt-5 min-h-84 rounded-lg py-0 shadow-none @xl/dashboard:h-64 @xl/dashboard:min-h-0 @4xl/dashboard:h-84">
        <CardContent className="flex h-full flex-col items-center justify-between gap-5 p-4 @xl/dashboard:flex-row @xl/dashboard:px-8 @4xl/dashboard:flex-col @4xl/dashboard:gap-4 @4xl/dashboard:px-4">
          <div className="order-1 @xl/dashboard:order-2 @4xl/dashboard:order-1">
            <CollectionDonutChart
              data={chartData}
              total={total}
              label={collectionOverview.label}
            />
          </div>
          <div className="order-2 flex w-full flex-col gap-2 @xl/dashboard:order-1 @xl/dashboard:max-w-64 @4xl/dashboard:order-2 @4xl/dashboard:max-w-none">
            {segments.map((segment) => (
              <div
                key={segment.label}
                className="text-secondary-foreground grid grid-cols-12 items-center text-base leading-snug"
              >
                <div className="text-secondary-foreground/80 col-span-6 flex min-w-0 items-center gap-2">
                  <span
                    className="size-3.5 shrink-0 rounded-sm"
                    style={{
                      backgroundColor: `var(--chart-${segment.color})`,
                    }}
                  />
                  <span>{segment.label}</span>
                </div>
                <span className="col-span-3 text-right font-medium tabular-nums">
                  {segment.count.toLocaleString()}
                </span>
                <span className="col-span-3 text-right font-medium tabular-nums">
                  {segment.percentage.toFixed(1)}%
                </span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

function RecentActivity() {
  return (
    <div>
      <SectionTitle>Recent Activity</SectionTitle>
      <div className="mt-5 space-y-6">
        {recentActivity.map((activity) => {
          const ActivityIcon = activity.icon;
          return (
            <div
              key={activity.id}
              className={cn(
                "flex gap-3",
                activity.id === "return" ? "items-center" : "items-start",
              )}
            >
              <div className="bg-secondary text-secondary-foreground flex size-11 shrink-0 items-center justify-center rounded-lg">
                <ActivityIcon className="size-5" />
              </div>
              <div className="text-secondary-foreground flex min-w-0 flex-1 items-start justify-between gap-4">
                <p className="w-full text-base leading-snug">
                  {activity.parts.map((part, index) => (
                    <span
                      key={`${activity.id}-${index}`}
                      className={cn(
                        "font-medium",
                        "muted" in part &&
                          part.muted &&
                          "text-muted-foreground font-normal",
                      )}
                    >
                      {part.text}
                    </span>
                  ))}
                </p>
                <time
                  dateTime={activity.dateTime}
                  className="text-secondary-foreground/80 shrink-0 text-xs leading-4 font-medium"
                >
                  {activity.time}
                </time>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function LibraryIntelligence() {
  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between">
        <SectionTitle>Library Intelligence</SectionTitle>
        <Button
          variant="ghost"
          size="sm"
          className="bg-transparent hover:bg-transparent dark:hover:bg-transparent"
        >
          <span>See all</span>
          <ArrowDown01Icon className="size-4 -rotate-90 transition-transform duration-200 ease-out group-hover/button:translate-x-1 motion-reduce:transform-none" />
        </Button>
      </div>
      <div className="mt-5 flex flex-1 flex-col justify-between gap-2">
        {intelligenceCards.map((card) => (
          <Card
            key={card.title}
            className="bg-secondary text-secondary-foreground rounded-lg border-0 py-0 shadow-none"
          >
            <CardContent className="p-3">
              <div className="flex items-center justify-between">
                <div
                  className={cn(
                    "flex items-center gap-1 text-sm font-semibold",
                    card.tone === "insight" && "text-[#c803c8]",
                    card.tone === "warning" && "text-[#d47c01]",
                    card.tone === "success" && "text-[#15823e]",
                  )}
                >
                  <SparklesIcon className="size-5" />
                  <span>{card.title}</span>
                </div>
                <Button
                  aria-label={`Dismiss ${card.title}`}
                  variant="ghost"
                  size="icon-xs"
                >
                  <CancelIcon className="size-5" />
                </Button>
              </div>
              <div className="mt-3 flex items-end gap-3">
                <p className="text-secondary-foreground min-w-0 flex-1 text-base leading-snug">
                  {card.bodyParts.map((part, index) => (
                    <span
                      key={`${card.title}-${index}`}
                      className={cn(
                        "emphasis" in part &&
                          part.emphasis &&
                          "text-secondary-foreground font-medium",
                      )}
                    >
                      {part.text}
                    </span>
                  ))}
                </p>
                <Button variant="ghost" size="sm">
                  <span>View</span>
                  <ArrowDown01Icon className="size-4 -rotate-90 transition-transform duration-200 ease-out group-hover/button:translate-x-1 motion-reduce:transform-none" />
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

